# Generated by build.py from recipe.yml for recipe http-rotate-a-fixed-bearer-token. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'token.txt'), "control-token-0123456789abcdefghij`n")
[IO.File]::WriteAllText((Join-Path $PWD 'bearer.json'), "{`"user`":`"`",`"password`":`"token-one`"}")
[IO.File]::WriteAllText((Join-Path $PWD 'rotate.json'), "{`"password`":`"token-two`"}")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--cert', 'server.pem', '--key', 'server.key', '--control', 'http://127.0.0.1:8081', '--control-token-file', 'token.txt', 'https://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -o NUL -w "%{scheme} %{response_code}\n" --json @bearer.json -H "Authorization: Bearer control-token-0123456789abcdefghij" http://127.0.0.1:8081/v1/accounts --next -s -o NUL -w "%{scheme} %{response_code}\n" --cacert server.pem https://127.0.0.1:8080/hello.txt --next -s -o NUL -w "%{scheme} %{response_code}\n" --cacert server.pem --oauth2-bearer token-one https://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
